const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

rl.on('line', (input) => {
    const n = parseInt(input.slice(0, -1));
    const s = input.slice(-1);
    const seatOrder = ['f', 'e', 'd', 'a', 'b', 'c'];
    const seatIndex = seatOrder.indexOf(s);
    let total = 0;

    // Determine the group of rows the current row belongs to
    let group = 0;
    let startRow = 1;
    while (startRow + 2 * group + 1 <= n) {
        group++;
    }

    // Calculate the number of complete groups before the current one
    let completeGroups = group;
    let rowsInCompleteGroups = completeGroups * 2;
    let rowsServedInCompleteGroups = rowsInCompleteGroups * 6;
    let timeMovingInCompleteGroups = 0;
    for (let i = 0; i < completeGroups; i++) {
        timeMovingInCompleteGroups += 2;
    }
    total += rowsServedInCompleteGroups + timeMovingInCompleteGroups;

    // Calculate the position within the current group
    let offset = n - (startRow + 2 * group);
    let rowsBeforeInGroup = offset;
    let rowsServedBeforeInGroup = rowsBeforeInGroup * 6;
    let timeMovingBeforeInGroup = rowsBeforeInGroup;
    total += rowsServedBeforeInGroup + timeMovingBeforeInGroup;

    // Add the time to serve up to the current seat
    total += seatIndex + 1;

    console.log(total);
    rl.close();
