const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim();
const n = parseInt(input.slice(0, -1));
const s = input.slice(-1);

const seatOrder = ['f', 'e', 'd', 'a', 'b', 'c'];
const seatIndex = seatOrder.indexOf(s);

let total = 0;

// Calculate the time taken before reaching the current row
// The attendants move in a pattern: 1,3 -> 2,4 -> 5,7 -> 6,8 -> 9,11 -> ...
// Each pair of rows takes 6 seconds (3 passengers per row * 2 rows) plus movement time
// Movement time between pairs: 1 second per row moved

// Determine which pair of rows the current row belongs to
// Pairs are: (1,3), (2,4), (5,7), (6,8), (9,11), (10,12), ...
// The pattern repeats every 4 rows: first pair starts at 1, second at 2, third at 5, fourth at 6, etc.

// Find the group of 4 rows that contains n
const group = Math.floor((n - 1) / 4);
const groupStart = group * 4 + 1;

// Determine if n is in the first or second pair of the group
let pairStart, pairEnd;
if (n === groupStart || n === groupStart + 1) {
    // First pair: (groupStart, groupStart + 2)
    pairStart = groupStart;
    pairEnd = groupStart + 2;
} else {
    // Second pair: (groupStart + 4, groupStart + 6)
    pairStart = groupStart + 4;
    pairEnd = groupStart + 6;
}

// Calculate time for all complete groups before the current one
// Each group has 2 pairs, each pair takes 6 seconds + movement
// Movement within group: 1 row (between pairs)
// Movement between groups: 3 rows (from pairEnd to next groupStart)

// Time for complete groups
const groupsBefore = group;
total += groupsBefore * (2 * 6 + 1 + 3); // 2 pairs * 6 sec + 1 sec move between pairs + 3 sec move to next group

// Time for pairs in the current group before the current pair
if (n === groupStart || n === groupStart + 1) {
    // First pair, no pairs before it in this group
} else {
    // Second pair, first pair takes 6 seconds + 1 second move
    total += 6 + 1;
}

// Time for the current pair up to the current row
// Each row in the pair takes 6 seconds
// If current row is the first in the pair, add 0
// If current row is the second in the pair, add 6 seconds
if (n === pairStart) {
    // First row in pair, no additional time for rows
} else {
    // Second row in pair, add 6 seconds for first row
    total += 6;
}

// Add time for serving passengers in the current row up to Vasya's seat
total += (seatIndex + 1);

console.log(total);
